Add a new migration, e.g. `C:\dk\supabase\migrations\0003_jobs_done_on_paid.sql`, and run it in the Supabase SQL editor. Do not edit 0001, because it is already applied.

```sql
create function recompute_tier(p_worker uuid) returns void language sql as $$
  update workers set tier = case
      when jobs_done >= 25 and rating_avg >= 4.5 and verified then 'star'
      when jobs_done >= 5  and rating_avg >= 4.0 then 'trusted'
      else 'new' end
  where profile_id = p_worker;
$$;

create function count_paid_job() returns trigger language plpgsql as $$
begin
  update workers set jobs_done = jobs_done + 1 where profile_id = new.worker_id;
  perform recompute_tier(new.worker_id);
  return null;
end $$;

create trigger requests_count_paid after update of status on requests
  for each row
  when (new.status in ('paid','rated') and old.status not in ('paid','rated'))
  execute function count_paid_job();

create or replace function apply_rating() returns trigger language plpgsql as $$
begin
  update workers w set
    rating_count = w.rating_count + 1,
    rating_avg   = round(((w.rating_avg * w.rating_count) + new.stars)::numeric / (w.rating_count + 1), 2)
  where w.profile_id = new.worker_id;
  perform recompute_tier(new.worker_id);
  update requests set status = 'rated' where id = new.request_id;
  return null;
end $$;
```

- **Counts once per job:** The WHEN clause counts a job on its first entry into 'paid'. It also counts a job that goes straight to 'rated' without ever being 'paid'.
- **No double count:** The paid -> rated update issued by `apply_rating` does not match the WHEN clause, so a rated job is not counted twice.
- **No client change:** After pay and rate, `jobs_done` ends at the same value as today, so the existing lifecycle check on rating -> reputation should still pass.
